// Get Hotchkiss deadline
const hDeadline = await browserjs(hotchkissTab, async () => {
  const resp = await fetch("https://www.hotchkiss.org/admission/how-to-apply");
  const html = await resp.text();
  const parser = new DOMParser();
  const doc = parser.parseFromString(html, "text/html");
  return doc.body.innerText;
});
const hDeadlineMatch = hDeadline.match(/(January|February|Jan|Feb|December|Dec)[^.\n]*\d{1,2}[^.\n]*/gi);
console.log("Hotchkiss deadline matches:", hDeadlineMatch);

// Get Choate tuition and deadline
const cData = await browserjs(choateTab, async () => {
  const r1 = await fetch("https://www.choate.edu/admission/tuition-and-financial-aid");
  const tText = (await r1.text()).replace(/<[^>]+>/g, ' ');
  const r2 = await fetch("https://www.choate.edu/admission/admission-process");
  const aText = (await r2.text()).replace(/<[^>]+>/g, ' ');
  return { tText: tText.slice(0, 5000), aText: aText.slice(0, 5000) };
});

const cTuitionMatch = cData.tText.match(/(\$[0-9,]+)/g);
console.log("Choate tuition matches:", cTuitionMatch);
const cDeadlineMatch = cData.aText.match(/(January|February|Jan|Feb)[^.\n]*\d{1,2}/gi);
console.log("Choate deadline matches:", cDeadlineMatch);

// Print Choate snippets
console.log("Choate tuition snippet:", cData.tText.slice(cData.tText.indexOf("Boarding") > -1 ? cData.tText.indexOf("Boarding") - 50 : 0, 800));
console.log("Choate apply snippet:", cData.aText.slice(cData.aText.indexOf("Deadline") > -1 ? cData.aText.indexOf("Deadline") - 50 : 0, 800));

