// Select all and clear
await tool.press({ tabId: padTabId, keys: "ControlOrMeta+a" });
await tool.press({ tabId: padTabId, keys: "Delete" });
await new Promise(r => setTimeout(r, 500));

// Go to A1
await tool.press({ tabId: padTabId, keys: "ControlOrMeta+Home" });
await new Promise(r => setTimeout(r, 500));

// Write to clipboard and paste
await browserjs(padTabId, async (tsv) => {
  await navigator.clipboard.writeText(tsv);
}, fullTSV);

await tool.press({ tabId: padTabId, keys: "ControlOrMeta+v" });
await new Promise(r => setTimeout(r, 2500));

const shot = await browser.screenshot({ tabId: padTabId });
console.log("Screenshot after populating sheet:", shot.image);

