  "1. Flagship Titans\tPhillips Exeter Academy (NH) and Phillips Academy Andover (MA): Unmatched academic offerings, collegiate resources, pure Harkness discussion method, need-blind admissions, and global prestige.",
  "2. 100% Boarding Communities\tSt. Paul's School (NH) and St. Andrew's School (DE): Rare 100% residential boarding environments where all students and faculty reside on campus, creating tight-knit communities.",
  "3. Best Value & Warmth\tGroton School (MA): Exceptional Ivy/top-college placement, small supportive community (~380 students), and the lowest tuition among top-tier peers ($62,740).",
  "4. West Coast Leader\tCate School (CA): Premier California option perched on the mesa near Santa Barbara, pairing academic rigor with outdoor spirit and ocean/mountain access.",
  "5. Distinctive Residential Model\tThe Lawrenceville School (NJ): Celebrated House System organizing students by form/class and robust Harkness teaching near Princeton."
].join("\n");

const fullTSV = header + "\n" + rows + "\n" + summarySection;

// Click spreadsheet canvas
await tool.mouse({ tabId: padTabId, action: "left_click", coordinate: [300, 450] });

// Select all and clear
await tool.press({ tabId: padTabId, keys: "ControlOrMeta+a" });
await tool.press({ tabId: padTabId, keys: "Delete" });
await new Promise(r => setTimeout(r, 500));

// Go to A1
await tool.press({ tabId: padTabId, keys: "ControlOrMeta+Home" });
await new Promise(r => setTimeout(r, 500));

// Write to clipboard and paste
await browserjs(padTabId, async (tsv) => {
  await navigator.clipboard.writeText(tsv);
}, fullTSV);

await tool.press({ tabId: padTabId, keys: "ControlOrMeta+v" });
await new Promise(r => setTimeout(r, 2500));

const shot = await browser.screenshot({ tabId: padTabId });
console.log("Screenshot after populating sheet:", shot.image);
"}

